const input = $input.first().json;

// Se veio pelo Chat Trigger nativo do n8n
if (input.chatInput !== undefined) {
  return [{
    json: {
      message: (input.chatInput || '').trim(),
      phone: '5531999998888',
      pushName: 'Carlos Teste',
      origem_lead: 'anuncio_serena_eco', // Opções: 'anuncio_serena_eco', 'anuncio_serena_130t', 'inbound_organico'
      produto_lead: 'Serena ECO',
      sessionId: input.sessionId || 'sessao_chat_ui_01',
      dados_iniciais: {}
    }
  }];
}

// Se veio pelo Webhook de teste automatizado (POST com JSON)
const body = input.body || input;
return [{
  json: {
    message: (body.message || body.chatInput || '').trim(),
    phone: body.phone || '5531999998888',
    pushName: body.pushName || 'Carlos Teste',
    origem_lead: body.origem_lead || body.origem || 'anuncio_serena_eco',
    produto_lead: body.produto_lead || body.produto || 'Serena ECO',
    sessionId: body.sessionId || body.phone || 'sessao_webhook_01',
    dados_iniciais: body.dados_iniciais || {}
  }
}];

const ctx = $input.first().json;

const leadNome = ctx.pushName || 'Produtor';
const primeiroNome = leadNome.split(' ')[0] || '';

// Identifica o foco do produto com base no anúncio ou na mensagem
const textoCompleto = [ctx.origem_lead, ctx.produto_lead, ctx.message].join(' ').toLowerCase();
let produtoFoco = 'Indefinido';

if (/eco\b|econ[oô]mica/.test(textoCompleto)) {
  produtoFoco = 'Serena ECO';
} else if (/130\s?t|cracker/.test(textoCompleto)) {
  produtoFoco = 'Serena 130T';
}

const dadosQual = Object.assign({
  area_atuacao: null,
  cidade: null,
  estado: null,
  intencao_compra: null,
  rebanho: null,
  vacas_lactacao: null,
  producao_diaria_litros: null,
  preco_litro: null,
  situacao_silagem: null,
  processamento_grao: null
}, ctx.dados_iniciais || {});

const dadosColetados = Object.entries(dadosQual)
  .filter(([_, v]) => v !== null && v !== undefined && v !== '')
  .map(([k, v]) => `${k}: ${v}`)
  .join(', ') || 'nenhum dado coletado ainda';

const contexto_sistema = `[CONTEXTO DO LEAD NESTE ATENDIMENTO]
- Nome do Lead: ${primeiroNome} (${leadNome})
- Telefone / WhatsApp: ${ctx.phone}
- Origem / Campanha: ${ctx.origem_lead || 'Contato direto'}
- Produto de Foco Inicial: ${produtoFoco}
- Dados já conhecidos no sistema: ${dadosColetados}
- Sessão de Atendimento: ${ctx.sessionId}
(Use este contexto para não repetir perguntas de dados que já foram respondidos!)`;

return [{
  json: Object.assign({}, ctx, {
    lead_first_name: primeiroNome,
    produto_foco: produtoFoco,
    dados_qualificacao: dadosQual,
    contexto_sistema: contexto_sistema
  })
}];

