return JSON.stringify(result);

const agentResp = $input.first().json;
const ctx = $('Preparar Contexto Lead').first().json;

const rawText = agentResp.output || '{}';
const cleaned = rawText
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let parsed = {};
try {
  parsed = JSON.parse(cleaned);
} catch(e) {
  parsed = { mensagem_whatsapp: cleaned, novos_dados: {}, acionar_especialista: false };
}

const mensagem = parsed.mensagem_whatsapp || cleaned;
const novos_dados = parsed.novos_dados || {};
const acionar_especialista = parsed.acionar_especialista === true;
const enviar_video = parsed.enviar_video_geral === true;

const dados_qual = Object.assign({}, ctx.dados_qualificacao, novos_dados);

// Determina se o foco final é Serena ECO ou 130T
let produtoFoco = ctx.produto_foco;
if (novos_dados.produto_interesse) {
  produtoFoco = novos_dados.produto_interesse;
}

// ── Scoring Específico ──────────────────────────────────────────────────
let score = 0;
const area = (dados_qual.area_atuacao || '').toLowerCase();
const estado = (dados_qual.estado || '').toUpperCase();
const intencao = (dados_qual.intencao_compra || '').toLowerCase();

// Região prioritária definida na reunião (MG e SP)
if (estado === 'MG' || estado === 'SP') {
  score += 25;
} else if (estado) {
  score += 10;
}

if (produtoFoco === 'Serena ECO') {
  // Lógica de Scoring Serena ECO (Mais enxuta e inclusiva)
  if (area.includes('leite') || area.includes('corte')) score += 30;

  if (intencao === 'imediata' || intencao === '60dias') score += 40;
  else if (intencao === 'safra' || intencao === '120dias') score += 25;
  else if (intencao === 'curiosidade') score += 5;

} else {
  // Lógica de Scoring Serena 130T (Foco em leite e volume)
  if (area.includes('leite')) score += 30;
  else if (area.includes('corte') || area.includes('misto')) score += 15;
  else if (area.includes('prestador')) score += 20;

  const rebanho = Number(dados_qual.rebanho) || 0;
  if (rebanho > 100) score += 35;
  else if (rebanho >= 50) score += 20;
  else if (rebanho > 0) score += 5;

  if (intencao === '60dias') score += 30;
  else if (intencao === '120dias') score += 15;
}

// ── Temperatura ──────────────────────────────────────────────────────────
let temperatura = 'FRIO';
if (score >= 80) temperatura = 'QUENTE';
else if (score >= 50) temperatura = 'MORNO';
else if (score >= 20) temperatura = 'FRIO';
else temperatura = 'DESCARTADO';

// ── Validação de Dados Completos ──────────────────────────────────────────
let dados_completos = false;
if (produtoFoco === 'Serena ECO') {
  // ECO só exige atividade, cidade, estado e momento de compra
  dados_completos = Boolean(dados_qual.area_atuacao && dados_qual.cidade && dados_qual.estado && dados_qual.intencao_compra);
} else {
  // 130T exige perfil mais completo
  const camposObrig130T = ['area_atuacao', 'rebanho', 'cidade', 'estado', 'intencao_compra'];
  dados_completos = camposObrig130T.every(c => Boolean(dados_qual[c]));
}

return [{
  json: Object.assign({}, ctx, {
    mensagem_whatsapp: mensagem,
    novos_dados: novos_dados,
    dados_qualificacao: dados_qual,
    produto_foco: produtoFoco,
    pontuacao: score,
    temperatura: temperatura,
    dados_completos: dados_completos,
    acionar_especialista: acionar_especialista,
    enviar_video: enviar_video
  })
}];

const ctx = $input.first().json;

// Formata substituição de [nome]
const primeiroNome = ctx.lead_first_name || '';
let msgFormatada = (ctx.mensagem_whatsapp || '')
  .replace(/\[nome\]/gi, primeiroNome)
  .replace(/\{nome\}/gi, primeiroNome)
  .replace(/\s*!\s*/g, '! ')
  .trim();

// Bloco visual de debug para facilitar testes no chat do n8n
const debugBlock = [
  "",
  "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━",
  "🛠️ [PAINEL DE TESTE SDR - BOTIER]",
  `• Produto de Foco: ${ctx.produto_foco}`,
  `• Score: ${ctx.pontuacao} pts | Temperatura: ${ctx.temperatura}`,
  `• Dados Completos: ${ctx.dados_completos ? '✅ SIM (Qualificado)' : '⏳ Em coleta'}`,
  `• Acionar Especialista (Diego): ${ctx.acionar_especialista ? '🚨 SIM (Lead Quente)' : 'Não'}`,
  `• Enviar Vídeo Geral: ${ctx.enviar_video ? '🎥 SIM' : 'Não'}`,
  `• Novos dados nesta rodada: ${JSON.stringify(ctx.novos_dados || {})}`,
  "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"
].join('\n');

const saidaChat = msgFormatada + debugBlock;

return [{
  json: {
    output: saidaChat,
    mensagem: msgFormatada,
    dados_qualificacao: ctx.dados_qualificacao,
    produto_foco: ctx.produto_foco,
    pontuacao: ctx.pontuacao,
    temperatura: ctx.temperatura,
    dados_completos: ctx.dados_completos,
    acionar_especialista: ctx.acionar_especialista,
    enviar_video: ctx.enviar_video,
    sessionId: ctx.sessionId
  }
}];
